#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
//! `POST /compat/v2/parse` with an OCR engine: image uploads and scanned PDFs read by
//! the OCR engine, the `ocr_unavailable` warning gone, `GET /parse/formats` listing the image types as
//! available. Scans are generated by the dependency-free writer of `crawlx-extract`'s tests.
//! Skips (printing why) without the `tesseract` binary.

#[path = "../../crawlx-extract/tests/support/scan.rs"]
mod scan;

use axum::body::Body;
use axum::http::{Method, Request, StatusCode};
use axum::Router;
use crawlx_api::auth::{generate_key, key_record, tenant_id_for};
use crawlx_api::{ApiConfig, AppState, Repos, Scope};
use crawlx_extract::parse::ocr::{Ocr, OcrBackend, OcrConfig, OcrError};
use crawlx_policy::AdmissionPolicy;
use crawlx_storage::MemoryStore;
use scan::PageKind;
use serde_json::{json, Value};
use std::sync::Arc;
use tower::ServiceExt;

const PARSE: &str = "/compat/v2/parse";
const BOUNDARY: &str = "----crawlxocrboundary";

fn engine() -> Option<Arc<Ocr>> {
    let config = OcrConfig {
        backend: OcrBackend::Tesseract,
        ..OcrConfig::default()
            .apply_env(&|k| (k == "TESSDATA_PREFIX").then(|| std::env::var(k).ok()).flatten())
            .unwrap()
    };
    match Ocr::shared(&config) {
        Ok(e) => e,
        Err(e @ OcrError::Unavailable { .. }) => {
            eprintln!("skipping: {e}");
            None
        }
        Err(e) => panic!("{e}"),
    }
}

struct T {
    app: Router,
    key: String,
}

fn build(ocr: Option<Arc<Ocr>>) -> T {
    let repos = Repos::memory(Arc::new(MemoryStore::new()));
    let clock: Arc<dyn crawlx_core::Clock> = Arc::new(crawlx_core::SystemClock);
    let config = ApiConfig {
        rate_limit_per_minute: 0,
        ..ApiConfig::default()
    };
    let mut b = AppState::builder(repos.clone(), AdmissionPolicy::new(clock.clone()), config).clock(clock);
    if let Some(o) = ocr {
        b = b.ocr(o);
    }
    let state = b.build();
    let app = crawlx_api::router(state);
    let key = generate_key();
    let rec = key_record(&key, tenant_id_for("acme"), Scope::all_set()).unwrap();
    futures::executor::block_on(async { repos.api.key_insert(&rec, "acme").await.unwrap() });
    T { app, key }
}

fn multipart(name: &str, bytes: &[u8], options: Option<&Value>) -> Vec<u8> {
    let mut body = Vec::new();
    body.extend_from_slice(
        format!("--{BOUNDARY}\r\nContent-Disposition: form-data; name=\"file\"; filename=\"{name}\"\r\n\r\n")
            .as_bytes(),
    );
    body.extend_from_slice(bytes);
    body.extend_from_slice(b"\r\n");
    if let Some(o) = options {
        body.extend_from_slice(
            format!(
                "--{BOUNDARY}\r\nContent-Disposition: form-data; name=\"options\"\r\nContent-Type: application/json\r\n\r\n{o}\r\n"
            )
            .as_bytes(),
        );
    }
    body.extend_from_slice(format!("--{BOUNDARY}--\r\n").as_bytes());
    body
}

impl T {
    async fn call(&self, req: Request<Body>) -> (StatusCode, Value) {
        let resp = self.app.clone().oneshot(req).await.unwrap();
        let (parts, body) = resp.into_parts();
        let bytes = axum::body::to_bytes(body, 64 * 1024 * 1024).await.unwrap();
        (
            parts.status,
            serde_json::from_slice(&bytes).unwrap_or(Value::Null),
        )
    }

    async fn upload(&self, name: &str, bytes: &[u8], options: Option<Value>) -> (StatusCode, Value) {
        let req = Request::builder()
            .method(Method::POST)
            .uri(PARSE)
            .header(
                "content-type",
                format!("multipart/form-data; boundary={BOUNDARY}"),
            )
            .header("authorization", format!("Bearer {}", self.key))
            .body(Body::from(multipart(name, bytes, options.as_ref())))
            .unwrap();
        self.call(req).await
    }

    async fn formats(&self) -> Value {
        let req = Request::builder()
            .uri("/compat/v2/parse/formats")
            .header("authorization", format!("Bearer {}", self.key))
            .body(Body::empty())
            .unwrap();
        self.call(req).await.1
    }
}

fn warnings(v: &Value) -> Vec<String> {
    v["data"]["warnings"]
        .as_array()
        .map(|w| w.iter().map(|w| w["code"].as_str().unwrap().to_owned()).collect())
        .unwrap_or_default()
}

fn available_images(v: &Value) -> Vec<String> {
    v["data"]["formats"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|f| f["kind"] == "image" && f["available"] == true)
        .map(|f| f["format"].as_str().unwrap().to_owned())
        .collect()
}

#[tokio::test]
async fn an_image_upload_is_refused_without_an_engine_and_read_with_one() {
    let (img, _) = scan::render_lines(&["HELLO WORLD", "SCANNED INVOICE"], 8);
    let png = scan::png(&img);
    let plain = build(None);
    assert!(available_images(&plain.formats().await).is_empty());
    let (s, v) = plain.upload("scan.png", &png, None).await;
    assert_eq!(s, StatusCode::UNSUPPORTED_MEDIA_TYPE, "{v}");
    let Some(ocr) = engine() else {
        return;
    };
    let t = build(Some(ocr));
    assert_eq!(
        available_images(&t.formats().await),
        ["png", "jpeg", "gif", "webp", "bmp", "tiff"]
    );
    let (s, v) = t.upload("scan.png", &png, None).await;
    assert_eq!(s, StatusCode::OK, "{v}");
    assert_eq!(
        scan::words(v["data"]["markdown"].as_str().unwrap()),
        "HELLO WORLD SCANNED INVOICE",
        "{v}"
    );
    assert_eq!(v["data"]["metadata"]["contentType"], "image/png");
    assert_eq!(v["data"]["metadata"]["ocrBackend"], "tesseract");
    assert!(
        v["data"]["metadata"]["ocrConfidence"].as_f64().unwrap() > 0.5,
        "{v}"
    );
}

#[tokio::test]
async fn a_scanned_pdf_is_read_in_auto_and_ocr_modes_and_not_in_fast_mode() {
    let Some(ocr) = engine() else {
        return;
    };
    let (text, _) = scan::render_lines(&["HELLO WORLD", "SCANNED INVOICE"], 8);
    let page = scan::on_page(&text, 1224, 1584, 100, 150);
    let pdf = scan::pdf(&[PageKind::Scan {
        img: &page,
        rotate: 0,
    }]);
    let t = build(Some(ocr));
    for mode in ["auto", "ocr"] {
        let (s, v) = t
            .upload(
                "scan.pdf",
                &pdf,
                Some(json!({"parsers": [{"type": "pdf", "mode": mode}]})),
            )
            .await;
        assert_eq!(s, StatusCode::OK, "{mode}: {v}");
        assert_eq!(
            scan::words(v["data"]["markdown"].as_str().unwrap()),
            "HELLO WORLD SCANNED INVOICE",
            "{mode}: {v}"
        );
        assert!(
            !warnings(&v).contains(&"ocr_unavailable".to_owned()),
            "{mode}: {v}"
        );
        assert_eq!(v["data"]["metadata"]["numPages"], 1);
    }
    let (s, v) = t
        .upload(
            "scan.pdf",
            &pdf,
            Some(json!({"parsers": [{"type": "pdf", "mode": "fast"}]})),
        )
        .await;
    assert_eq!(s, StatusCode::UNPROCESSABLE_ENTITY, "{v}");
    assert_eq!(v["code"], "no_text_layer");
}

#[tokio::test]
async fn ocr_blocks_carry_the_engine_and_confidence() {
    let Some(ocr) = engine() else {
        return;
    };
    let (text, _) = scan::render_lines(&["HELLO WORLD"], 8);
    let page = scan::on_page(&text, 1224, 1584, 100, 150);
    let pdf = scan::pdf(&[PageKind::Scan {
        img: &page,
        rotate: 0,
    }]);
    let (s, v) = build(Some(ocr))
        .upload(
            "scan.pdf",
            &pdf,
            Some(json!({"parsers": [{"type": "pdf", "blocks": true}]})),
        )
        .await;
    assert_eq!(s, StatusCode::OK, "{v}");
    let block = &v["data"]["blocks"][0]["items"][0];
    assert_eq!(block["source"], "ocr", "{v}");
    assert!(block["confidence"]["ocr"].as_f64().unwrap() > 0.5, "{block}");
}
